 "content": "def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0]); bg=g[0][0]
    # Solid divider lines specify the axis. The motif acts as a displacement:
    # paint the separator-color target lane just beyond the motif's extent.
    d=next((r for r,row in enumerate(g) if len(set(row))==1 and row[0]!=bg),None)
    if d is not None:
        div=g[d][0]; rows=[r for r in range(h) if any(v not in (bg,div) for v in g[r])]
        if rows:
            gap=max(rows)+1 if max(rows)<d else min(rows)-1
            if 0<=gap<h:
                for c in range(w):
                    if g[gap][c]==bg:g[gap][c]=8
        return g
    d=next((c for c in range(w) if all(g[r][c]==g[0][c] and g[0][c]!=bg for r in range(h))),None)
    if d is not None:
        div=g[0][d]; cols=[c for c in range(w) if any(g[r][c] not in (bg,div) for r in range(h))]
        if cols:
            gap=max(cols)+1 if max(cols)<d else min(cols)-1
            if 0<=gap<w:
                for r in range(h):
                    if g[r][gap]==bg:g[r][gap]=8
    return g
